/**
 * BI-26.2 —— bin 级伪端点 e2e:零网络、零密钥、可回归的全链路验收。
 *
 * 走真实 bin 入口(bin/bi.ts):配置装载(临时 HOME 的三级 TOML)→ BI-02 凭据门
 * (BI_FAKE_KEY 环境变量)→ BI-04.2 双模态适配器 → 本地伪端点(127.0.0.1)→
 * stream-json 输出断言。与 ignition-real-model.ts 的差异:实弹点火需真端点真
 * 密钥(手动/定期),本套件 CI 可跑(门控 BI_PTY_E2E=1,本地开发缺省跳过以保
 * 持开发环轻快)。
 * 纪律:子进程 env 仅 PATH+HOME+BI_FAKE_KEY——宿主任何真实凭据不透传,
 * 结构性杜绝真实外呼。
 */
import { describe, expect, test } from "bun:test";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { startFakeEndpoint } from "./fake-endpoint.ts";

const ROOT = join(import.meta.dir, "..");
const RUN = process.env.BI_PTY_E2E === "1";

async function makeHome(providerKind: "anthropic" | "openai", baseUrl: string): Promise<string> {
	const home = await mkdtemp(join(tmpdir(), "bi-fake-e2e-"));
	await mkdir(join(home, ".bi"), { recursive: true });
	const config = [
		"[providers.entries.fake]",
		'api_key_env = "BI_FAKE_KEY"',
		`base_url = "${baseUrl}"`,
		`kind = "${providerKind}"`,
		'models = ["fake-echo"]',
		"",
		"[providers]",
		'default = "fake"',
		"",
		"[models]",
		'default = "main"',
		"",
		"[models.entries.main]",
		'provider = "fake"',
		'model = "fake-echo"',
		"",
	].join("\n");
	await writeFile(join(home, ".bi", "config.toml"), config, { mode: 0o600 });
	return home;
}

describe.skipIf(!RUN)("BI-26.2 伪端点 bin e2e", () => {
	test("anthropic 模式:bin --prompt 全链路回环(ECHO 上屏+session_done)", async () => {
		const fake = startFakeEndpoint({ echo: true, mode: "anthropic" });
		const home = await makeHome("anthropic", fake.url);
		try {
			const proc = Bun.spawn(["bun", join(ROOT, "bin", "bi.ts"), "--prompt", "你好伪端点"], {
				stdout: "pipe",
				stderr: "pipe",
				env: { PATH: process.env.PATH ?? "/usr/bin", HOME: home, BI_FAKE_KEY: "dummy" },
			});
			const stdout = await new Response(proc.stdout).text();
			const stderr = await new Response(proc.stderr).text();
			const code = await proc.exited;
			expect(code).toBe(0);
			expect(fake.requests.length).toBeGreaterThan(0);
			expect(stdout).toContain('"type":"content_delta"');
			expect(stdout).toContain("ECHO:你好伪端点");
			expect(stdout).toContain('"exit":"ok"');
			expect(stdout).toContain('"finalText":"ECHO:你好伪端点"');
			// 装配面在 stderr:provider/mode/model 三元组可见
			expect(stderr).toContain("mode=messages");
		} finally {
			fake.close();
			await rm(home, { recursive: true, force: true });
		}
	}, 60_000);

	test("openai 模式:resolveModelPort 选择链→适配器直连伪端点", async () => {
		const { ConfigService } = await import("../packages/core/src/config/config-service");
		const { resolveModelPort } = await import("../packages/core/src/cli/model-port");
		const fake = startFakeEndpoint({ echo: true, mode: "openai" });
		const home = await makeHome("openai", fake.url);
		try {
			const service = new ConfigService({ homeDir: home, workDir: home });
			const config = await service.load();
			// 凭据面走 options.env(注入),不经 service.resolveProviderApiKey(读进程 env)
			const selection = resolveModelPort(config, {
				env: { BI_FAKE_KEY: "dummy" },
			});
			expect(selection.mode).toBe("openai");
			const events = [];
			for await (const event of selection.port.stream({
				messages: [{ role: "user", content: "openai 模式回环" }],
				tools: [],
			})) {
				events.push(event);
			}
			const text = events
				.filter((e) => e.type === "content_delta")
				.map((e) => (e as { delta: string }).delta)
				.join("");
			expect(text).toBe("ECHO:openai 模式回环");
			expect(events.at(-1)).toMatchObject({ type: "done", stopReason: "stop" });
		} finally {
			fake.close();
			await rm(home, { recursive: true, force: true });
		}
	}, 60_000);
});

/**
 * BI-26.2 —— 本地伪模型端点(bin 级零网络零密钥 e2e 的驱动器)。
 *
 * 用 Bun.serve 在 127.0.0.1 随机端口模拟 Anthropic/OpenAI 双模态 SSE 端点:
 * - anthropic 模式:任意以 /anthropic/v1/messages 结尾的路径,标准
 *   message_start → content_block_delta(text_delta) → message_delta(end_turn)
 *   → message_stop 事件序列(与 BI-04.2 适配器解析契约逐字段对齐);
 * - openai 模式:任意以 /chat/completions 结尾的路径,chunk delta + finish_reason
 *   + [DONE] 终帧。
 * 回复语义:echo=true 时提取请求最后一条 user 消息文本回显(`ECHO:<text>`),
 * 供 e2e 断言"输入→模型→上屏"全回环;固定 text 优先。
 * EMPTY_RESPONSE 防御:适配器对零内容+finish=stop 判 protocol 错,故任何
 * 脚本至少含一个 text_delta。
 * 安全:仅绑定 127.0.0.1;进程内显式 close;不含任何真实凭据。
 */

export interface FakeEndpointOptions {
	/** 固定回复文本(优先于 echo)。 */
	readonly text?: string;
	/** true=回显请求最后一条 user 消息文本(ECHO:<text>)。 */
	readonly echo?: boolean;
	/** 指定端口;缺省 0=随机空闲端口。 */
	readonly port?: number;
}

export interface FakeEndpoint {
	/** 形如 http://127.0.0.1:<port>(anthropic 配置直填 base_url;openai 配置亦直填,路径后缀自适应)。 */
	readonly url: string;
	readonly port: number;
	/** 收到的请求体(JSON.parse 后;调试/断言用)。 */
	readonly requests: readonly Record<string, unknown>[];
	close(): void;
}

function lastUserText(body: Record<string, unknown>): string {
	const messages = body.messages;
	if (!Array.isArray(messages)) return "";
	for (let i = messages.length - 1; i >= 0; i--) {
		const m = messages[i] as { role?: unknown; content?: unknown } | null;
		if (m === null || m.role !== "user") continue;
		if (typeof m.content === "string") return m.content;
		if (Array.isArray(m.content)) {
			const parts = m.content
				.filter((b): b is { type: string; text?: string } =>
					typeof b === "object" && b !== null && (b as { type?: unknown }).type === "text",
				)
				.map((b) => (typeof b.text === "string" ? b.text : ""));
			return parts.join("");
		}
	}
	return "";
}

export function startFakeEndpoint(options: FakeEndpointOptions = {}): FakeEndpoint {
	const requests: Array<Record<string, unknown>> = [];

	const replyText = (body: Record<string, unknown>): string => {
		if (options.text !== undefined) return options.text;
		if (options.echo === true) return `ECHO:${lastUserText(body)}`;
		return "ECHO:";
	};

	const sse = (frames: string[]): Response =>
		new Response(frames.map((f) => `data: ${f}\n\n`).join(""), {
			status: 200,
			headers: { "content-type": "text/event-stream" },
		});

	const server = Bun.serve({
		port: options.port ?? 0,
		hostname: "127.0.0.1",
		fetch: async (req) => {
			const url = new URL(req.url);
			let body: Record<string, unknown> = {};
			try {
				const raw = await req.text();
				const parsed: unknown = raw === "" ? {} : JSON.parse(raw);
				if (typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)) {
					body = parsed as Record<string, unknown>;
				}
			} catch {
				body = {};
			}
			requests.push(body);
			const text = replyText(body);
			if (url.pathname.endsWith("/chat/completions")) {
				return sse([
					JSON.stringify({ choices: [{ delta: { role: "assistant", content: text } }] }),
					JSON.stringify({ choices: [{ delta: {}, finish_reason: "stop" }] }),
					"[DONE]",
				]);
			}
			if (url.pathname.endsWith("/anthropic/v1/messages")) {
				return sse([
					JSON.stringify({
						type: "message_start",
						message: { usage: { input_tokens: 8 } },
					}),
					JSON.stringify({
						type: "content_block_delta",
						index: 0,
						delta: { type: "text_delta", text },
					}),
					JSON.stringify({
						type: "message_delta",
						delta: { stop_reason: "end_turn" },
						usage: { output_tokens: 3 },
					}),
					JSON.stringify({ type: "message_stop" }),
				]);
			}
			return new Response(JSON.stringify({ error: "not-found" }), { status: 404 });
		},
	});

	const boundPort = server.port ?? 0;
	return {
		url: `http://127.0.0.1:${boundPort}`,
		port: boundPort,
		requests,
		close: () => server.stop(true),
	};
}

/**
 * BI-23.3 —— 真实模型端口装配配件：BI-04.2 双模态适配器 → BI-23.1 ModelPort。
 *
 * 职责边界（装配层只选择与映射，器官不改动）：
 * - `createAdapterModelPort`：直连形态（baseUrl/apiKey/model 直传），e2e 与注入用；
 * - `resolveModelPort`：BiConfig 选择逻辑（providers/models/thinking 三段）+ 凭据门
 *   （BI-02：`api_key_env` 间接引用，key 只经环境变量解析，永不落盘、永不入日志）；
 * - kind → WireMode：openai → 'openai'，anthropic → 'messages'，google 无已装配
 *   驱动 → 结构化报错（BI-23.3 交付面 = openai/anthropic 两协议）；
 * - thinking.effort（minimal/low/medium/high）→ 适配器档位（off/low/high/max）：
 *   minimal→off、low→low、medium→high、high→max；`thinking.enabled=false` 强制 off。
 *
 * 失败面全部结构化（`ModelPortConfigError`），由 main 分发映射退出码 3
 * （凭据未配置 / 配置缺失 / 无驱动协议），不静默降级、不伪造端口。
 */
import {
	buildRequest,
	DeepSeekAdapter,
	type FetchLike,
	type StreamEvent,
	type ThinkingEffort,
	type WireMode,
} from "../adapters/deepseek-adapter";
import type { BiConfig } from "../config/schema";
import type { ModelPort } from "./headless";

/** 模型装配失败（配置缺失 / 凭据未设置 / 无驱动协议）的结构化信号。 */
export class ModelPortConfigError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "ModelPortConfigError";
	}
}

/** kind → WireMode；未知协议结构化报错（不猜测、不降级）。 */
function wireModeFromKind(kind: string): WireMode {
	if (kind === "openai") return "openai";
	if (kind === "anthropic") return "messages";
	throw new ModelPortConfigError(
		`provider kind "${kind}" 暂无已装配驱动（BI-23.3 交付 openai/anthropic 两协议）`,
	);
}

/** bi 思考档位 → 适配器四档；enabled=false 强制 off。 */
export function effortToAdapter(enabled: boolean, effort: string): ThinkingEffort {
	if (!enabled) return "off";
	switch (effort) {
		case "minimal":
			return "off";
		case "low":
			return "low";
		case "medium":
			return "high";
		case "high":
			return "max";
		default:
			return "off";
	}
}

/** 缺省凭据门：api_key_env → 环境变量；未声明 = 无静态 Key（OAuth/本地端点）。 */
function resolveApiKeyFromEnv(
	providerName: string,
	envName: string,
	env: Record<string, string | undefined>,
): string {
	if (envName === "") return "";
	const key = env[envName];
	if (key === undefined || key === "") {
		throw new ModelPortConfigError(
			`环境变量 ${envName} 未设置：provider "${providerName}" 通过 api_key_env 间接引用 API 密钥。` +
				`请导出 ${envName} 后重试；配置文件中永不落明文密钥。`,
		);
	}
	return key;
}

/** 直连适配器端口构造参数。 */
export interface AdapterModelPortOptions {
	baseUrl: string;
	apiKey: string;
	/** 供应商侧模型名。 */
	model: string;
	/** Wire 形态；缺省 'messages'（Anthropic 规范子集）。 */
	mode?: WireMode;
	thinking?: ThinkingEffort;
	maxTokens?: number;
	temperature?: number;
	/** 注入 fetch（离线测试用）；缺省 globalThis.fetch。 */
	fetchImpl?: FetchLike;
	anthropicVersion?: string;
}

/** 直连形态：BI-04.2 双模态适配器包装为 ModelPort（每回合按当前消息重建请求）。 */
export function createAdapterModelPort(options: AdapterModelPortOptions): ModelPort {
	const mode: WireMode = options.mode ?? "messages";
	const adapter = DeepSeekAdapter({
		baseUrl: options.baseUrl,
		apiKey: options.apiKey,
		...(options.fetchImpl === undefined ? {} : { fetchImpl: options.fetchImpl }),
		...(options.anthropicVersion === undefined ? {} : { anthropicVersion: options.anthropicVersion }),
	});
	return {
		stream({ messages, tools, signal }): AsyncIterable<StreamEvent> {
			const request = buildRequest([...messages], {
				mode,
				model: options.model,
				...(options.thinking === undefined ? {} : { thinking: options.thinking }),
				...(options.maxTokens !== undefined && options.maxTokens > 0
					? { maxTokens: options.maxTokens }
					: {}),
				...(options.temperature === undefined ? {} : { temperature: options.temperature }),
				...(tools.length > 0 ? { tools: [...tools] } : {}),
				stream: true,
			});
			return adapter.stream(request, signal);
		},
	};
}

/** 装配结果（诊断用元数据 + 可用端口）。 */
export interface ModelSelection {
	readonly port: ModelPort;
	readonly providerName: string;
	/** models.entries 键（bi 侧模型 ID）。 */
	readonly modelId: string;
	/** 供应商侧模型名。 */
	readonly wireModel: string;
	readonly mode: WireMode;
	readonly baseUrl: string;
	readonly thinking: ThinkingEffort;
}

export interface ResolveModelPortOptions {
	/** 环境变量源（缺省 process.env；api_key_env 解析用）。 */
	env?: Record<string, string | undefined>;
	/** 注入 fetch（离线测试用）。 */
	fetchImpl?: FetchLike;
	/**
	 * 凭据门注入：main 传 `ConfigService.resolveProviderApiKey` 以复用其修复指引
	 * 与 ConfigError 形态；缺省用内置 env 直读（测试注入 env 用）。
	 */
	resolveApiKey?: (providerName: string) => string | undefined;
}

function firstKey(record: Record<string, unknown>): string | undefined {
	for (const key of Object.keys(record)) return key;
	return undefined;
}

/**
 * BiConfig → 真实 ModelPort。选择链：models.default（空 = entries 首个）→
 * 条目引用 provider（空 = providers.default → entries 首个）→ kind 定协议 →
 * 凭据门解析 key → 端口构造。任何一步缺失都结构化报错（含修复指引）。
 */
export function resolveModelPort(
	config: BiConfig,
	options: ResolveModelPortOptions = {},
): ModelSelection {
	const env = options.env ?? process.env;

	const modelId =
		config.models.default !== "" ? config.models.default : firstKey(config.models.entries);
	if (modelId === undefined || modelId === "") {
		throw new ModelPortConfigError(
			"未配置对话模型：请在 ~/.bi/config.toml 设置 [models.default] 并在 [models.entries.<id>] 声明 provider 与 model",
		);
	}
	const modelEntry = config.models.entries[modelId];
	if (modelEntry === undefined) {
		throw new ModelPortConfigError(`模型 "${modelId}"（models.default）不在 models.entries 中`);
	}

	const providerName =
		modelEntry.provider !== ""
			? modelEntry.provider
			: (config.providers.default !== "" ? config.providers.default : firstKey(config.providers.entries));
	if (providerName === undefined || providerName === "") {
		throw new ModelPortConfigError(
			`模型 "${modelId}" 未引用 provider：请补 [models.entries.${modelId}].provider 或 [providers.default]`,
		);
	}
	const providerEntry = config.providers.entries[providerName];
	if (providerEntry === undefined) {
		throw new ModelPortConfigError(
			`provider "${providerName}" 不在 providers.entries 中（模型 "${modelId}" 引用了它）`,
		);
	}

	const mode = wireModeFromKind(providerEntry.kind);
	if (modelEntry.model === "") {
		throw new ModelPortConfigError(`模型 "${modelId}" 缺供应商侧模型名（model 字段为空）`);
	}

	const apiKey =
		options.resolveApiKey !== undefined
			? (options.resolveApiKey(providerName) ?? "")
			: resolveApiKeyFromEnv(providerName, providerEntry.api_key_env, env);

	const thinking = effortToAdapter(config.thinking.enabled, config.thinking.effort);

	return {
		port: createAdapterModelPort({
			baseUrl: providerEntry.base_url,
			apiKey,
			model: modelEntry.model,
			mode,
			thinking,
			...(modelEntry.max_tokens > 0 ? { maxTokens: modelEntry.max_tokens } : {}),
			...(modelEntry.temperature === undefined ? {} : { temperature: modelEntry.temperature }),
			...(options.fetchImpl === undefined ? {} : { fetchImpl: options.fetchImpl }),
		}),
		providerName,
		modelId,
		wireModel: modelEntry.model,
		mode,
		baseUrl: providerEntry.base_url,
		thinking,
	};
}

