export type ProvidersSection = InferSchema<typeof providersSchema>;

export const modelEntrySchema = sEntity({
  /** 引用的 provider 名（providers.entries 的键）。 */
  provider: sStr(""),
  /** 供应商侧模型名（如 "kimi-k2-turbo-preview"）。 */
  model: sStr(""),
